export const agentMarkdownByPath: Readonly<Record<string, string>> = {
  "/": "# temporal-calendar\n\n> Temporal-first building blocks for month, week, and day calendar interfaces.\n\nCanonical: https://calendar.gobrand.app/\n\nCoding agents should read https://calendar.gobrand.app/llms.txt before making Calendar changes.\n\nInstall the Calendar Agent Skill with `npx skills add go-brand/calendar`.\n\nReact installation: `pnpm add @gobrand/react-calendar @js-temporal/polyfill`.\n\nHuman documentation: https://calendar.gobrand.app/docs.\n",
  "/docs": "# React Calendar\n\n> Build month, week, and day calendars with React and Temporal.\n\nCanonical: https://calendar.gobrand.app/docs\n\nReact Calendar manages the current date, active view, navigation, and calendar geometry. You render it with your own components and styles.\n\nStart with one view and your events:\n\n```tsx\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useCreateCalendar } from '@gobrand/react-calendar'\n\ntype Event = {\n  id: string\n  title: string\n  date: Temporal.PlainDate\n}\n\nfunction Calendar({ events }: { events: Event[] }) {\n  const calendar = useCreateCalendar({\n    views: { month: true },\n    items: events,\n    getDate: event => event.date,\n  })\n\n  return calendar.activeView.weeks.map(week => (\n    <div key={week[0].id}>\n      {week.map(day => (\n        <div key={day.id}>\n          {day.date.toString()}: {day.items.length} events\n        </div>\n      ))}\n    </div>\n  ))\n}\n```\n\nBecause only `month` is enabled, `activeView` is a month view. Add `week` or `day` when you need them.\n\n[Build your first calendar](/docs/first-calendar) or [open the complete month/week/day example](/docs/examples/multi-view).\n",
  "/docs/installation": "# Installation\n\n> Get started with GoBrand React Calendar\n\nCanonical: https://calendar.gobrand.app/docs/installation\n\n## Install\n\n```bash\npnpm add @gobrand/react-calendar @js-temporal/polyfill\n# or\nnpm install @gobrand/react-calendar @js-temporal/polyfill\n```\n\nThe React package includes the core library - no separate installation needed.\n\n## TypeScript\n\nThe package is written in TypeScript and includes type definitions. No additional `@types` packages needed.\n\n## Temporal\n\nImport Temporal from the polyfill you installed above:\n\n```typescript\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst today = Temporal.Now.plainDateISO();\nconst meeting = Temporal.ZonedDateTime.from('2025-01-20T14:00:00-05:00[America/New_York]');\n```\n",
  "/docs/first-calendar": "# Your first calendar\n\n> Build a navigable month with one hook.\n\nCanonical: https://calendar.gobrand.app/docs/first-calendar\n\nEnable a view with `true`, pass your events, and tell the calendar where each event belongs.\n\n```tsx\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useCreateCalendar } from '@gobrand/react-calendar'\n\ntype Event = {\n  id: string\n  title: string\n  date: Temporal.PlainDate\n}\n\nfunction Calendar({ events }: { events: Event[] }) {\n  const calendar = useCreateCalendar({\n    views: { month: true },\n    items: events,\n    getDate: event => event.date,\n  })\n\n  return (\n    <section>\n      <h2>{calendar.title()}</h2>\n      {calendar.activeView.weeks.flat().map(day => (\n        <div key={day.id}>\n          {day.date.toString()}: {day.items.map(event => event.title).join(', ')}\n        </div>\n      ))}\n    </section>\n  )\n}\n```\n\nThat is the whole setup. TypeScript infers the event type, and `calendar.activeView` is a `MonthView` because month is the only enabled view.\n\n[Complete basic-month source](https://calendar.gobrand.app/examples/basic-month.md) (export `BasicMonthExample`).\n\nThe preview is live. Its source uses small website-only components for markup and styles; its calendar state and month data come directly from `useCreateCalendar`.\n\n## What the library does\n\n- Keeps the current date and active view.\n- Moves with `previous()`, `next()`, and `today()`.\n- Gives you a localized `title()` and timezone-aware `visibleRange`.\n- Builds the month, week, or day data you render.\n\nYour app owns the markup, styles, data fetching, and caching.\n\n## Add week and day views\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: {\n    month: true,\n    week: true,\n    day: true,\n  },\n  items: events,\n  getDate: event => event.date,\n})\n```\n\nAn omitted view is unavailable. Use an options object instead of `true` when a timed week or day needs custom hours or slot length.\n\n[See the complete month/week/day example](/docs/examples/multi-view).\n\nFor application integration, see [event timezone mapping](/docs/timezones-and-ranges) and [controller lifetime and controlled state](/docs/controlled-state).\n",
  "/docs/data-and-suspense": "# Data and Suspense\n\n> Keep calendar controls available while a view loads its events.\n\nCanonical: https://calendar.gobrand.app/docs/data-and-suspense\n\nCreate the calendar without events above the Suspense boundary. Fetch and project the events inside the view.\n\n```tsx\nimport { Suspense } from 'react'\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useSuspenseQuery } from '@tanstack/react-query'\nimport {\n  CalendarProvider,\n  useCalendar,\n  useCalendarView,\n  useCreateCalendar,\n} from '@gobrand/react-calendar'\n\ntype Event = {\n  id: string\n  title: string\n  date: Temporal.PlainDate\n}\n\ntype CalendarProps = {\n  loadEvents(\n    start: Temporal.ZonedDateTime,\n    end: Temporal.ZonedDateTime,\n  ): Promise<Event[]>\n}\n\nfunction Calendar({ loadEvents }: CalendarProps) {\n  const calendar = useCreateCalendar({ views: { month: true } })\n\n  return (\n    <CalendarProvider calendar={calendar}>\n      <Controls />\n      <Suspense fallback={<p>Loading events…</p>}>\n        <MonthView loadEvents={loadEvents} />\n      </Suspense>\n    </CalendarProvider>\n  )\n}\n\nfunction Controls() {\n  const calendar = useCalendar()\n\n  return (\n    <nav>\n      <button onClick={calendar.previous}>Previous</button>\n      <strong>{calendar.title()}</strong>\n      <button onClick={calendar.next}>Next</button>\n    </nav>\n  )\n}\n\nfunction MonthView({ loadEvents }: CalendarProps) {\n  const calendar = useCalendar()\n  const { start, end } = calendar.visibleRange\n  const { data: events } = useSuspenseQuery({\n    queryKey: ['events', start.toString(), end.toString()],\n    queryFn: () => loadEvents(start, end),\n  })\n\n  const month = useCalendarView({\n    view: 'month',\n    items: events,\n    getDate: event => event.date,\n  })\n\n  return month.weeks.map(week => (\n    <div key={week[0].id}>\n      {week.map(day => (\n        <div key={day.id}>\n          {day.date.toString()}: {day.items.map(event => event.title).join(', ')}\n        </div>\n      ))}\n    </div>\n  ))\n}\n```\n\n`Controls` does not unmount when `MonthView` suspends, so navigation remains available while events load.\nThe example assumes your app already has TanStack Query's `QueryClientProvider`.\n\n## Different data for each view\n\nEach `useCalendarView` call infers its own item type. A month view can use summaries while a timed week view uses full event records. The shared controller does not need to know either type.\n\n[Complete suspense-month source](https://calendar.gobrand.app/examples/suspense-month.md) (export `SuspenseMonthExample`).\n",
  "/docs/timezones-and-ranges": "# Timezones and visible ranges\n\n> Query half-open calendar ranges that remain correct across DST transitions.\n\nCanonical: https://calendar.gobrand.app/docs/timezones-and-ranges\n\nSet the calendar timezone once:\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: { month: true, week: true },\n  timeZone: 'America/New_York',\n})\n```\n\nThat timezone drives the initial date, `today()`, `isToday`, navigation ranges, and local-midnight boundaries. Calendar behavior does not fall back to the host timezone after a timezone is supplied.\n\n## Half-open query contract\n\n```ts\ntype VisibleRange = {\n  start: Temporal.ZonedDateTime\n  end: Temporal.ZonedDateTime\n}\n```\n\nUse `>= start` and `< end`. Adjacent ranges meet without gaps or duplicate boundary records, and the code never has to invent the final nanosecond of a day.\n\n```ts\nconst { start, end } = calendar.visibleRange\n\nawait db.event.findMany({\n  where: {\n    startsAt: { gte: start.toInstant(), lt: end.toInstant() },\n  },\n})\n```\n\n## DST is calendar geometry\n\nA local calendar day may contain 23, 24, or 25 elapsed hours. Calendar constructs each boundary from its own local midnight rather than adding 24 hours to an instant.\n\n## Event mapping belongs to your data layer\n\nThe controller timezone defines geometry. Accessors decide which local date and start time each item belongs to; setting `timeZone` does not convert your items. Normalize an event once, then derive both accessors from that same value:\n\n```ts\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst normalizedEvent = {\n  title: 'Late UTC meeting',\n  start: Temporal.Instant.from('2026-07-10T23:30:00Z')\n    .toZonedDateTimeISO('Europe/Madrid'),\n};\nconst getDate = (event: typeof normalizedEvent) => event.start.toPlainDate();\nconst getStart = (event: typeof normalizedEvent) => event.start;\n// getDate(normalizedEvent).toString() === '2026-07-11'\n// getStart(normalizedEvent).hour === 1\n```\n\nPass these accessors with the normalized items to the projection. The UTC date is July 10; the Madrid calendar date is July 11.\n",
  "/docs/controlled-state": "# Controlled state and routing\n\n> Synchronize calendar date and view with URLs or external application state.\n\nCanonical: https://calendar.gobrand.app/docs/controlled-state\n\nCalendar follows standard React controlled and uncontrolled conventions.\n\n| State | Controlled | Uncontrolled initial value |\n| --- | --- | --- |\n| Date | `date` / `onDateChange` | `defaultDate` |\n| View | `view` / `onViewChange` | `defaultView` |\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: { month: true, week: true },\n  date: search.date,\n  view: search.view,\n  onDateChange: date => navigate({ search: previous => ({ ...previous, date }) }),\n  onViewChange: view => navigate({ search: previous => ({ ...previous, view }) }),\n})\n```\n\nProp changes are reflected immediately. This matters for browser back/forward navigation: consumers do not need an effect that mutates a controller after render.\n\n## Geometry changes\n\nChanging `timeZone`, `weekStartsOn`, `dayStart`, `dayEnd`, or `slotDuration` recreates the underlying controller from the new value signature. The visible range therefore cannot retain initial configuration accidentally.\n\n## Controller and action lifetime\n\nController and action identities can change across renders. Read actions from the current controller. Subscriptions must follow that controller and clean up when it changes:\n\n```tsx\nuseEffect(() => calendar.subscribe(() => {\n  console.log(calendar.date.toString());\n}), [calendar]);\n```\n\nThe callback reads the controller subscribed by that effect. Do not capture the first controller or an action indefinitely.\n",
  "/docs/api/use-create-calendar": "# useCreateCalendar\n\n> Create a controlled or uncontrolled item-agnostic controller, with optional simple-mode data.\n\nCanonical: https://calendar.gobrand.app/docs/api/use-create-calendar\n\n```tsx\nconst calendar = useCreateCalendar({\n  views: { month: true, week: true },\n  defaultDate: Temporal.PlainDate.from('2026-07-10'),\n  defaultView: 'month',\n  timeZone: 'America/Asuncion',\n  items: events,\n  getDate: event => event.date,\n})\n```\n\nWith `items`, the return value includes the inferred `activeView`. Without `items`, it returns the item-agnostic controller used with `CalendarProvider` and `useCalendarView`.\n\nControlled props are `date`/`onDateChange` and `view`/`onViewChange`; uncontrolled initial props are `defaultDate` and `defaultView`.\n",
  "/docs/api/use-calendar": "# useCalendar\n\n> Read the item-agnostic calendar controller from context.\n\nCanonical: https://calendar.gobrand.app/docs/api/use-calendar\n\n```tsx\nfunction Toolbar() {\n  const calendar = useCalendar()\n  return (\n    <button onClick={calendar.next}>{calendar.title()}</button>\n  )\n}\n```\n\nThe hook accepts no item generic. Item types belong to `useCalendarView` calls below the provider.\n",
  "/docs/api/use-calendar-view": "# useCalendarView\n\n> Put events into one view from a shared calendar controller.\n\nCanonical: https://calendar.gobrand.app/docs/api/use-calendar-view\n\n`useCalendarView` reads the controller from `CalendarProvider` unless you pass `calendar` directly. TypeScript infers the item type from `items`.\n\n```tsx\nimport type { Temporal } from '@js-temporal/polyfill'\nimport { useCalendarView } from '@gobrand/react-calendar'\n\ntype Event = {\n  id: string\n  title: string\n  startsAt: Temporal.ZonedDateTime\n}\n\nfunction WeekContent({ events }: { events: Event[] }) {\n  const week = useCalendarView({\n    view: 'week',\n    items: events,\n    getDate: event => event.startsAt.toPlainDate(),\n    getStart: event => event.startsAt,\n  })\n\n  return week.days.map(day => (\n    <div key={day.id}>\n      {day.date.toString()}: {day.items.map(event => event.title).join(', ')}\n    </div>\n  ))\n}\n```\n\n`getDate` is required when you pass `items`. `getStart` is optional. Add it when events should appear in timed slots.\n",
  "/docs/api/calendar-provider": "# CalendarProvider\n\n> Share one calendar controller with child components.\n\nCanonical: https://calendar.gobrand.app/docs/api/calendar-provider\n\n```tsx\nimport {\n  CalendarProvider,\n  useCalendar,\n  useCreateCalendar,\n} from '@gobrand/react-calendar'\n\nfunction Calendar() {\n  const calendar = useCreateCalendar({ views: { month: true } })\n\n  return (\n    <CalendarProvider calendar={calendar}>\n      <Controls />\n      <VisibleRange />\n    </CalendarProvider>\n  )\n}\n\nfunction Controls() {\n  const calendar = useCalendar()\n\n  return (\n    <nav>\n      <button onClick={calendar.previous}>Previous</button>\n      <strong>{calendar.title()}</strong>\n      <button onClick={calendar.next}>Next</button>\n    </nav>\n  )\n}\n\nfunction VisibleRange() {\n  const { visibleRange } = useCalendar()\n\n  return <p>{visibleRange.start.toString()} – {visibleRange.end.toString()}</p>\n}\n```\n\nThe provider shares calendar state, not event data. Child views can fetch their own records and use their own item types.\n",
  "/docs/types/calendar": "# Calendar Controller\n\n> Item-agnostic calendar state, navigation, and visible query range.\n\nCanonical: https://calendar.gobrand.app/docs/types/calendar\n\n`CalendarController<TViews>` exposes `date`, `view`, typed `viewNames`, resolved `views`, `visibleRange`, `title`, `setDate`, `setView`, `next`, `previous`, `today`, and `subscribe`.\n\nDirect controllers preserve the exact configured-view union. Context exposes the honest built-in `ViewName` boundary because distant consumers cannot infer the provider's exact value.\n",
  "/docs/types/views": "# View Models\n\n> Discriminated month, week, and day models with locally inferred items.\n\nCanonical: https://calendar.gobrand.app/docs/types/views\n\n`MonthView<TItem>`, `WeekView<TItem>`, and `DayView<TItem>` are discriminated by their `name` field. `ActiveView<TViews, TItem>` narrows the union to the configured views.\n\nThe old `view` field remains as a deprecated alias for compatibility. New code should use `name`.\n\nTimed week and day configuration uses `Temporal.PlainTime` for `dayStart`/`dayEnd` and `Temporal.Duration` for `slotDuration`.\n",
  "/docs/types/helpers": "# Range and Configuration Types\n\n> Public types for configured views, geometry, and half-open query ranges.\n\nCanonical: https://calendar.gobrand.app/docs/types/helpers\n\n`VisibleRange` is `{ start, end }`, where both values are `Temporal.ZonedDateTime` instances in the controller timezone. Query with `>= start` and `< end`.\n\n`NonEmptyCalendarViews` enforces at least one of `month`, `week`, or `day`; JavaScript consumers receive the same validation synchronously at runtime.\n",
  "/docs/examples/basic-month": "# Month View\n\n> A complete month with navigation and events.\n\nCanonical: https://calendar.gobrand.app/docs/examples/basic-month\n\n[Complete basic-month source](https://calendar.gobrand.app/examples/basic-month.md) (export `BasicMonthExample`).\n\nThe source imports small website-only components from `./calendar-ui` for markup and styles. All calendar state and projection calls come from `@gobrand/react-calendar`.\n\nThis example needs only `getDate` because month cells group events by calendar date. Timed placement is introduced in the week and day examples.\n",
  "/docs/examples/date-picker": "# Date Picker\n\n> Select a date in a month without event data or accessors.\n\nCanonical: https://calendar.gobrand.app/docs/examples/date-picker\n\n[Complete date-picker source](https://calendar.gobrand.app/examples/date-picker.md) (export `DatePickerExample`).\n\nThe controller owns the selected date and navigation. A data-free month projection supplies the dates to render.\n",
  "/docs/examples/week-view": "# Week View\n\n> Build a simple week or add explicit time slots.\n\nCanonical: https://calendar.gobrand.app/docs/examples/week-view\n\n## Simple week\n\nEvents appear on each day.\n\n[Complete simple-week source](https://calendar.gobrand.app/examples/simple-week.md) (export `SimpleWeekExample`).\n\n## Week with time slots\n\nTimed events appear in an hourly grid.\n\n[Complete week-slots source](https://calendar.gobrand.app/examples/week-slots.md) (export `WeekSlotsExample`).\n\nBoth sources import small website-only components from `./calendar-ui` for markup and styles. All calendar state and projection calls come from `@gobrand/react-calendar`.\n",
  "/docs/examples/day-view": "# Day View\n\n> A day timeline with explicit Temporal time slots.\n\nCanonical: https://calendar.gobrand.app/docs/examples/day-view\n\n[Complete day-view source](https://calendar.gobrand.app/examples/day-view.md) (export `DayViewExample`).\n\nThe source imports small website-only components from `./calendar-ui` for markup and styles. All calendar state and projection calls come from `@gobrand/react-calendar`.\n",
  "/docs/examples/multi-view": "# Multi-View Calendar\n\n> One calendar that switches between month, week, and day.\n\nCanonical: https://calendar.gobrand.app/docs/examples/multi-view\n\n[Complete multi-view source](https://calendar.gobrand.app/examples/multi-view.md) (export `MultiViewExample`).\n\nThe source imports small website-only components from `./calendar-ui` for markup and styles. All calendar state and projection calls come from `@gobrand/react-calendar`.\n\nThis example uses local events so view switching is the only new concept. See [Suspense Query](/docs/examples/suspense-query) for async data.\n",
  "/docs/examples/suspense-query": "# Suspense Query\n\n> Keep month navigation available while its events load.\n\nCanonical: https://calendar.gobrand.app/docs/examples/suspense-query\n\n[Complete suspense-month source](https://calendar.gobrand.app/examples/suspense-month.md) (export `SuspenseMonthExample`).\n\nThe controller and toolbar stay above the Suspense boundary. The query and month projection run below it after data is ready.\n",
  "/docs/core": "# Calendar Core\n\n> Framework-agnostic Temporal controller and pure calendar projections.\n\nCanonical: https://calendar.gobrand.app/docs/core\n\n```ts\nimport { Temporal } from '@js-temporal/polyfill'\nimport { createCalendar, buildMonthView } from '@gobrand/calendar-core'\n\ntype Event = {\n  id: string\n  title: string\n  date: Temporal.PlainDate\n}\n\nconst events: Event[] = [\n  { id: 'launch', title: 'Launch', date: Temporal.Now.plainDateISO() },\n]\n\nconst calendar = createCalendar({\n  views: { month: true },\n})\n\nconst month = buildMonthView({\n  calendar,\n  items: events,\n  getDate: event => event.date,\n})\n```\n\nThe calendar starts on today in the device timezone. Pass `date` or `timeZone` only when your app needs to control them.\n",
  "/docs/core/installation": "# Installation\n\n> Get started with GoBrand Calendar Core\n\nCanonical: https://calendar.gobrand.app/docs/core/installation\n\n## Install\n\n```bash\npnpm add @gobrand/calendar-core\n# or\nnpm install @gobrand/calendar-core\n```\n\n## TypeScript\n\nThe package is written in TypeScript and includes type definitions. No additional `@types` packages needed.\n\n## Temporal Polyfill\n\nThe Temporal API is included via `@js-temporal/polyfill`. You can import Temporal types directly from the polyfill:\n\n```typescript\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst today = Temporal.Now.plainDateISO();\nconst meeting = Temporal.ZonedDateTime.from('2025-01-20T14:00:00-05:00[America/New_York]');\n```\n",
  "/docs/core/create-calendar": "# createCalendar\n\n> Create an item-agnostic controller from a non-empty view configuration.\n\nCanonical: https://calendar.gobrand.app/docs/core/create-calendar\n\n```ts\nconst calendar = createCalendar({\n  views: {\n    month: true,\n    week: {\n      dayStart: Temporal.PlainTime.from('08:00'),\n      dayEnd: Temporal.PlainTime.from('18:00'),\n      slotDuration: Temporal.Duration.from({ minutes: 30 }),\n    },\n  },\n  date: Temporal.PlainDate.from('2026-07-10'),\n  timeZone: 'America/Asuncion',\n})\n```\n\nThe visible range is always derived from `date`, `view`, timezone, and view configuration. It cannot become stale independently.\n\n`weekStartsOn` follows Temporal's `dayOfWeek` convention: `1` is Monday through\n`7` is Sunday. Omit it to use the locale default.\n",
  "/docs/core/projections": "# View Projections\n\n> Build month, week, and day models from controller state and local data.\n\nCanonical: https://calendar.gobrand.app/docs/core/projections\n\nCore exports `buildMonthView`, `buildWeekView`, and `buildDayView`. Each projection infers its own item type, so one controller can support unrelated query results.\n\n```ts\nconst month = buildMonthView({\n  calendar,\n  items: summaries,\n  getDate: summary => summary.date,\n})\n\nconst week = buildWeekView({\n  calendar,\n  items: events,\n  getDate: event => event.startsAt.toPlainDate(),\n  getStart: event => event.startsAt,\n})\n```\n\nCalling a projection without `items` returns a data-free grid and needs no accessor or fake item type.\n",
  "/docs/core/visible-ranges": "# Visible ranges\n\n> Understand Calendar's timezone-aware, half-open query boundary.\n\nCanonical: https://calendar.gobrand.app/docs/core/visible-ranges\n\nEvery controller derives a `VisibleRange` from its date, active view, timezone, and week configuration:\n\n```ts\nconst { start, end } = calendar.visibleRange\n```\n\n`start` is included. `end` is the local midnight immediately after the visible interval and is excluded.\n\n```sql\nWHERE starts_at >= :start\n  AND starts_at < :end\n```\n\nMonth ranges include the complete leading and trailing weeks rendered by the month projection. Week ranges contain seven local dates. Day ranges span one local calendar date—even when DST makes that date 23 or 25 elapsed hours.\n\nCalendar produces `Temporal.ZonedDateTime` boundaries so callers can preserve the timezone or convert explicitly with `.toInstant()` for storage queries.\n",
  "/docs/core/utilities": "# Utilities\n\n> Weekday labels and direct Temporal recipes for formatting, navigation, and timezone conversion.\n\nCanonical: https://calendar.gobrand.app/docs/core/utilities\n\nThe core package exports five values: `createCalendar`, `buildMonthView`, `buildWeekView`, `buildDayView`, and `getWeekdays`. Use Temporal directly for other date operations.\n\n## Formatting\n\n### getWeekdays\n\nGet localized weekday names in calendar order. Temporal uses `1` for Monday through `7` for Sunday.\n\n```typescript\nimport { getWeekdays } from '@gobrand/calendar-core';\n\ngetWeekdays(); // Monday start, short English names\ngetWeekdays(7); // Sunday start\ngetWeekdays(1, 'es-ES');\ngetWeekdays(1, 'en-US', 'long');\ngetWeekdays(7, 'en-US', 'narrow');\n```\n\n### getMonthName\n\nFormat a Temporal month directly; there is no `getMonthName` package export.\n\n```typescript\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst month = Temporal.PlainYearMonth.from('2025-01');\nmonth.toLocaleString('es-ES', { month: 'long' }); // enero\n```\n\n### formatTime\n\n```typescript\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst time = Temporal.PlainTime.from('14:30');\ntime.toLocaleString('en-GB', { hour: '2-digit', minute: '2-digit' });\n```\n\n## Timezone\n\n### getCurrentTimeZone\n\nUse `Temporal.Now.timeZoneId()` to obtain the system timezone.\n\n### convertToTimezone\n\n```typescript\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst ny = Temporal.ZonedDateTime.from('2025-01-15T14:00:00-05:00[America/New_York]');\nconst tokyo = ny.withTimeZone('Asia/Tokyo');\n// 2025-01-16T04:00:00+09:00[Asia/Tokyo]\n```\n\n### createZonedDateTime\n\n```typescript\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst date = Temporal.PlainDate.from('2025-01-15');\nconst time = Temporal.PlainTime.from('14:30');\nconst zoned = date.toZonedDateTime({ timeZone: 'America/New_York', plainTime: time });\n```\n\n## Navigation\n\nUse controller `next()`, `previous()`, and `today()` for the active view. For standalone calculations, Temporal supports explicit units:\n\n```typescript\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst date = Temporal.PlainDate.from('2025-01-15');\ndate.add({ months: 1 });\ndate.subtract({ weeks: 1 });\ndate.add({ days: 1 });\n```\n\n## Date Ranges\n\nUse the controller's half-open visible range for querying data:\n\n```typescript\nimport { createCalendar } from '@gobrand/calendar-core';\nimport { Temporal } from '@js-temporal/polyfill';\n\nconst calendar = createCalendar({\n  views: { month: true },\n  date: Temporal.PlainDate.from('2025-01-15'),\n  timeZone: 'America/New_York',\n});\nconst { start, end } = calendar.visibleRange;\n```\n\nQuery `>= start` and `< end`. See [timezones and ranges](/docs/timezones-and-ranges).\n\n## Layout Helpers\n\nCalendar is headless. Week and day projections provide Temporal geometry and items; your rendering code chooses CSS dimensions and event layout. The package does not export CSS positioning helpers. See the [complete week example](/docs/examples/week-view).\n"
};
